  'side deltoids': ['delts'],
  'lateral deltoids': ['delts'],
  'rear deltoids': ['rearDelts'],
  'rear delts': ['rearDelts'],
  'posterior deltoids': ['rearDelts'],
  'rotator cuff': ['rotatorCuff'],
  quadriceps: ['quads'],
  core: ['abs', ['obliques', 0.8]],
  abdominals: ['abs'],
  'lower abs': ['lowerAbs'],
  'upper abs': ['upperAbs'],
  obliques: ['obliques'],
  chest: ['chest'],
  'upper chest': ['upperChest'],
  'lower chest': ['lowerChest'],
  'hip flexors': ['hipFlexors'],
  'lower back': ['lowerBack'],
  'erector spinae': ['lowerBack'],
  back: ['lats', ['rhomboids', 0.6], ['lowerBack', 0.6]],
  'middle back': ['rhomboids', 'lowerTraps'],
  'mid back': ['rhomboids', 'lowerTraps'],
  rhomboids: ['rhomboids'],
  trapezius: ['traps'],
  'upper traps': ['upperTraps'],
  'latissimus dorsi': ['lats'],
  brachialis: ['biceps'],
  brachioradialis: ['forearms'],
  wrists: ['forearms'],
  'wrist flexors': ['forearms'],
